import {SemanticCommandBus} from '../../foundation/global/commands.js';
import {CollectionTableMatrixPresentationCore,                                       } from '../../foundation/collection/table-matrix.js';
import {defineContextDescriptorProvider} from '../../foundation/global/context-descriptor-contract.js';
import {createFamilyWorkspaceBinding} from '../../foundation/workspace-host.js';
import {ReleasesDomainAdapter,RELEASES_COMMANDS} from '../../adapters/releases/domain-adapter.js';
export const RELEASES_SURFACE_ID='releases';
export function createReleasesSurfaceComposition({adapter=null,commands=new SemanticCommandBus(),analyticalCompareOwner=null}={}){
  adapter=adapter||new ReleasesDomainAdapter({analyticalCompareOwner});
  adapter.bindCommands(commands);
  const tableAdapter                                        ={adapterId:'releases.candidates',rows:()=>adapter.rows(),rowId:r=>r.candidateId,rowLabel:r=>r.candidateId,searchableText:r=>`${r.candidateId} ${r.commitSHA} ${r.treeSHA} ${r.artifactDigest} ${r.state} ${r.authorization} ${r.deployment}`,columns:[{id:'candidate',label:'Candidate',cell:r=>({text:r.candidateId,secondary:r.commitSHA,direction:'ltr'})},{id:'readiness',label:'Technical readiness',cell:r=>({text:r.state,tone:r.state==='TECHNICALLY_READY'?'success':r.state==='NOT_READY'?'danger':'warning'})},{id:'evidence',label:'Candidate evidence',cell:r=>({text:r.evidenceDigest?'BOUND':'MISSING',secondary:r.evidenceDigest||'No candidate-bound evidence',tone:r.evidenceDigest?'success':'warning',direction:'ltr'})},{id:'authorization',label:'Owner authorization',cell:r=>({text:r.authorization})},{id:'deployment',label:'Deployment observation',cell:r=>({text:r.deployment,tone:r.deployment==='DEPLOYED'?'success':r.deployment==='FAILED'?'danger':r.deployment==='UNKNOWN'?'warning':'default'})}],actions:()=>[{id:'releases.inspect',label:'Inspect'},{id:'releases.compare',label:'Compare exact pair'},{id:'releases.plan',label:'Plan'}]};
  const collection=new CollectionTableMatrixPresentationCore(tableAdapter);
  const contextProvider=defineContextDescriptorProvider({id:'releases.context',family:'releases',owner:adapter.owner,describe:({id}    ={})=>{const row=adapter.rows().find(item=>item.candidateId===(id??adapter.selected()?.candidateId));return {id:`releases:${row?.candidateId||'empty'}`,providerId:'releases.context',family:'releases',subject:row?.candidateId||'No ReleaseCandidate selected',eyebrow:'Releases',summary:row?`${row.state} · authorization ${row.authorization} · deployment ${row.deployment}`:'No candidate means no green readiness.',domainOwner:adapter.owner,revisionToken:row?.artifactDigest||null,lenses:[{id:'identity',label:'Exact candidate',tabs:[{id:'candidate',label:'Candidate',fields:row?[{id:'commit',label:'Commit SHA',value:row.commitSHA,technical:true},{id:'tree',label:'Tree SHA',value:row.treeSHA,technical:true},{id:'artifact',label:'Artifact digest',value:row.artifactDigest,technical:true},{id:'evidence',label:'Evidence digest',value:row.evidenceDigest||'MISSING',technical:true},{id:'authorization',label:'Owner authorization',value:row.authorization},{id:'deployment',label:'Deployment observation',value:row.deployment},{id:'deploymentObservedAt',label:'Deployment observed at',value:row.deploymentObservedAt||'UNOBSERVED',technical:true}]:[]}]}]};}});
  return {surface:RELEASES_SURFACE_ID,workspaceBinding:createFamilyWorkspaceBinding({id:'releases.workspace',family:'global',domainKind:'releases',label:'Releases'}),adapter,commands,collection,tableAdapter,contextProvider,toolbarCommandIds:[...RELEASES_COMMANDS],bottomProjection:()=>adapter.diagnosticProjection(),compareBinding:{owner:'AnalyticalCompareOwner',providerId:'releases.exact-candidate.v1',pairSemantics:'TWO_EXACT_PINNED_RELEASE_CANDIDATES'},truthCeiling:{technicalReadinessIsOwnerAuthorization:false,ownerAuthorizationIsDeployment:false,readinessExecutesDeployment:false,authorizationExecutesDeployment:false},providerTruth:{deploymentExecution:'NOT_OWNED',deploymentObservationMayBe:'UNKNOWN'},platformTruth:{activeKeyboardSource:'UNAVAILABLE_OR_FALLBACK',nativeWindow:'UNAVAILABLE_OR_SEPARATE_PLATFORM_CAPABILITY'},slots:{TOP:'shared',TOOLBAR:'shared',LEFT:'collection',CENTER:'ReleaseGovernanceWorkbench',RIGHT:'shared-context-inspector',BOTTOM:'shared-bottom-shell/domain-projection',TRANSIENT:'shared'}};
}
